sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var gr = new GlideRecord('x_1882833_organi_0_meisai');
    gr.addQuery('name_kanji', current.name_kanji);
    gr.addQuery('kenmu_number', '!=', '主務');
    gr.query();

    var day = current.hatureibi;
    var month = day.substring(0, 8);
    var day_fix = day.substring(8, 10);
    var day_fix2 = '01';
    if (day_fix == 1) {
        day_fix = 1;
        day_fix2 = '01';
    } else if (day_fix < 16) {
        day_fix = 1;
        day_fix2 = '01';
        // gs.addErrorMessage('発令日は1日か16日を選択してください');
    } else if (day_fix == 16) {
        day_fix = 16;
        day_fix2 = '16';
    } else {
        day_fix = 16;
        day_fix2 = '16';
        // gs.addErrorMessage('発令日は1日か16日を選択してください。');
    }
    var ans = month + day_fix;
    var ans2 = month + day_fix2;

    current.hatureibi = ans;
	var str = '[' + ans2 + ']' + current.name.getDisplayValue() + '(' + current.number + ')'
    current.name_kanji = str;

    while (gr.next()) {
        gr.name_kanji = str;
        gr.update();
    }

})(current, previous);
